          [
            rule_section(:aim, "\u0413\u043E",
              "\u0413\u043E \u0432\u043E\u0437\u043D\u0438\u043A\u043B\u043E \u0432 \u041A\u0438\u0442\u0430\u0435. \u0414\u0432\u0430 \u0438\u0433\u0440\u043E\u043A\u0430 \u0441\u0442\u0430\u0432\u044F\u0442 \u0447\u0451\u0440\u043D\u044B\u0435 \u0438 \u0431\u0435\u043B\u044B\u0435 \u043A\u0430\u043C\u043D\u0438 \u043D\u0430 \u043F\u0435\u0440\u0435\u0441\u0435\u0447\u0435\u043D\u0438\u044F\u0445; \u0447\u0451\u0440\u043D\u044B\u0435 \u043D\u0430\u0447\u0438\u043D\u0430\u044E\u0442. \u041A\u0430\u043C\u043D\u0438, \u0441\u0432\u044F\u0437\u0430\u043D\u043D\u044B\u0435 \u0441\u0442\u043E\u0440\u043E\u043D\u0430\u043C\u0438, \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0442 \u0433\u0440\u0443\u043F\u043F\u0443. \u0421\u043E\u0441\u0435\u0434\u043D\u0438\u0439 \u043F\u0443\u0441\u0442\u043E\u0439 \u043F\u0443\u043D\u043A\u0442 \u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0441\u0432\u043E\u0431\u043E\u0434\u043E\u0439. \u0413\u0440\u0443\u043F\u043F\u0430 \u0431\u0435\u0437 \u0441\u0432\u043E\u0431\u043E\u0434 \u0441\u043D\u0438\u043C\u0430\u0435\u0442\u0441\u044F. \u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0441\u043D\u0438\u043C\u0430\u044E\u0442\u0441\u044F \u0437\u0430\u0445\u0432\u0430\u0447\u0435\u043D\u043D\u044B\u0435 \u043A\u0430\u043C\u043D\u0438 \u043F\u0440\u043E\u0442\u0438\u0432\u043D\u0438\u043A\u0430; \u0441\u0430\u043C\u043E\u0443\u0431\u0438\u0439\u0441\u0442\u0432\u043E \u0437\u0430\u043F\u0440\u0435\u0449\u0435\u043D\u043E."),
            rule_section(:variants, "\u0412\u0430\u0440\u0438\u0430\u043D\u0442\u044B",
              "\u0414\u043E\u0441\u043A\u0438 9, 13 \u0438\u043B\u0438 19 \u043F\u0443\u043D\u043A\u0442\u043E\u0432 \u043F\u043E \u0441\u0442\u043E\u0440\u043E\u043D\u0435. \u041F\u043E\u0434\u0441\u0447\u0451\u0442 \u043F\u043B\u043E\u0449\u0430\u0434\u0438 \u0432 \u043A\u0438\u0442\u0430\u0439\u0441\u043A\u043E\u043C \u0441\u0442\u0438\u043B\u0435 \u0441\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0435\u0442 \u0436\u0438\u0432\u044B\u0435 \u043A\u0430\u043C\u043D\u0438 \u0438 \u043E\u043A\u0440\u0443\u0436\u0451\u043D\u043D\u044B\u0435 \u043F\u0443\u0441\u0442\u044B\u0435 \u043F\u0443\u043D\u043A\u0442\u044B. \u041F\u043E\u0434\u0441\u0447\u0451\u0442 \u0442\u0435\u0440\u0440\u0438\u0442\u043E\u0440\u0438\u0438 \u0441\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0435\u0442 \u043F\u0443\u0441\u0442\u044B\u0435 \u043F\u0443\u043D\u043A\u0442\u044B, \u043F\u043B\u0435\u043D\u043D\u044B\u0445 \u0438 \u0441\u043E\u0433\u043B\u0430\u0441\u043E\u0432\u0430\u043D\u043D\u044B\u0435 \u043C\u0451\u0440\u0442\u0432\u044B\u0435 \u043A\u0430\u043C\u043D\u0438 \u043F\u0440\u043E\u0442\u0438\u0432\u043D\u0438\u043A\u0430. \u0411\u0435\u043B\u044B\u0435 \u043F\u043E\u043B\u0443\u0447\u0430\u044E\u0442 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0435 \u043A\u043E\u043C\u0438. \u0412 \u0410\u0442\u0430\u0440\u0438-\u0433\u043E \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043F\u0435\u0440\u0432\u044B\u0439 \u0437\u0430\u0445\u0432\u0430\u0442; \u0434\u0432\u0430 \u043F\u0430\u0441\u0430 \u0434\u0430\u044E\u0442 \u043D\u0438\u0447\u044C\u044E. \u0412\u043E \u0432\u0441\u0435\u0445 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0430\u0445 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u043F\u043E\u0437\u0438\u0446\u0438\u043E\u043D\u043D\u043E\u0435 \u0441\u0443\u043F\u0435\u0440\u043A\u043E. \u0422\u0435\u0440\u0440\u0438\u0442\u043E\u0440\u0438\u0430\u043B\u044C\u043D\u044B\u0439 \u0432\u0430\u0440\u0438\u0430\u043D\u0442 \u0442\u0440\u0435\u0431\u0443\u0435\u04